# -*- coding: utf-8 -*-
import json

def make_lesson(grade, num, ch_num, ch_title, title, summary, formulas, equations, theory, q, a, reagents):
    code_prefix = f"HH{grade}"
    clean_title = title.split(':', 1)[1].strip() if ':' in title else title
    return {
        "id": f"hh{grade}_b{num}",
        "code": f"{code_prefix}-B{num:02d}",
        "lessonNumber": num,
        "grade": grade,
        "chapterNumber": ch_num,
        "chapterTitle": ch_title,
        "title": {
            "VN": title,
            "EN": f"Lesson {num}: {clean_title}"
        },
        "summary": {
            "VN": summary,
            "EN": summary
        },
        "keyFormulas": formulas if isinstance(formulas, list) else [formulas],
        "equations": equations if isinstance(equations, list) else [equations],
        "theoryPoints": [{"VN": t, "EN": t} for t in (theory if isinstance(theory, list) else [theory])],
        "sampleQuestion": {
            "question": {"VN": q, "EN": q},
            "answer": {"VN": a, "EN": a}
        },
        "suggestedReagents": reagents if isinstance(reagents, list) else [reagents]
    }

def parse_raw_item(grade, ch_map, item):
    num = item[0]
    ch_num = item[1]
    ch_title = ch_map.get(ch_num, f"Chương {ch_num}")
    title = item[2]
    summary = item[3]
    formulas = item[4] if len(item) > 4 and isinstance(item[4], list) else []
    equations = item[5] if len(item) > 5 and isinstance(item[5], list) else []
    theory = item[6] if len(item) > 6 and isinstance(item[6], list) else ["Nắm vững kiến thức trọng tâm của bài học."]
    
    if len(item) >= 10:
        q = item[7]
        a = item[8]
        reagents = item[9] if isinstance(item[9], list) else [item[9]]
    elif len(item) == 9:
        q = item[7]
        a = item[8]
        # Infer relevant default reagents
        if grade == 11 and num == 12:
            reagents = ["ACETIC_ACID", "ETHANOL"]
        elif grade == 11 and num == 22:
            reagents = ["ETHANOL", "GLYCEROL", "PHENOL", "CuSO4", "NaOH", "BROMINE"]
        elif grade == 11 and num == 23:
            reagents = ["ACETALDEHYDE", "TOLLENS_REAGENT", "CuSO4", "NaOH"]
        elif grade == 11 and num == 24:
            reagents = ["ACETIC_ACID", "ETHANOL", "NaHCO3", "H2SO4"]
        else:
            reagents = ["WATER", "NaOH", "HCl"]
    else:
        q = "Câu hỏi củng cố trọng tâm bài học?"
        a = "Xem sách giáo khoa và thực hành trực tiếp trên bàn thí nghiệm."
        reagents = ["WATER"]
        
    return make_lesson(grade, num, ch_num, ch_title, title, summary, formulas, equations, theory, q, a, reagents)

