    (9, 3, "Bài 9: Amino Acid & Peptide", "Amino acid chứa nhóm -NH2 và -COOH (lưỡng tính). Peptide gồm 2 đến 50 gốc α-amino acid liên kết peptit (-CO-NH-). Phản ứng màu Biuret.", ["H₂N-CH₂-COOH (Glycine, M=75)", "H₂N-CH(CH₃)-COOH (Alanine, M=89)"], ["Phản ứng Biuret: Peptide từ 2 liên kết peptit trở lên (Tripeptide) + Cu(OH)₂ → Phức tím"], ["Amino acid có tính chất lưỡng tính tác dụng cả axit và kiềm."], "Dipeptide Gly-Ala có tham gia phản ứng màu Biuret với Cu(OH)2 không?", "KHÔNG, vì phản ứng Biuret đòi hỏi từ Tripeptide trở lên.", ["CuSO4", "NaOH", "HCl"]),
    (10, 3, "Bài 10: Protein & Enzyme", "Protein là polypeptide cao phân tử (>50 gốc). Bị đông tụ bởi nhiệt/axit. Phản ứng màu Biuret và phản ứng với HNO3 đặc.", ["Đông tụ protein khi đun nóng hoặc thêm cồn/axit", "Tác dụng HNO₃ đặc tạo kết tủa màu vàng (xanthoproteic)"], ["Enzyme làm tăng tốc độ phản ứng sinh hóa lên hàng triệu lần."], ["Protein là nền tảng cấu tạo nên sự sống."], "Nhỏ vài giọt HNO3 đặc vào lòng trắng trứng có hiện tượng gì?", "Xuất hiện kết tủa màu VÀNG.", ["HNO3", "CuSO4", "NaOH", "ETHANOL"]),
    (11, 3, "Bài 11: Ôn tập chương 3", "Hệ thống hóa cấu trúc amine, amino acid, liên kết peptit và phản ứng màu biuret.", ["Bài toán thủy phân peptide: Số mắt xích = Số liên kết peptit + 1", "m_peptide + m_H2O = m_amino acid"], ["Thành thạo bài toán amino acid tác dụng axit rồi kiềm."], ["Củng cố kỹ năng tính toán khối lượng phân tử peptide."], "Một tripeptide mạch hở chứa bao nhiêu liên kết peptit?", "Chứa 2 liên kết peptit (3 - 1 = 2).", ["CuSO4", "NaOH", "HCl", "HNO3"]),
    (12, 4, "Bài 12: Đại cương về Polymer", "Polymer là hợp chất có phân tử khối rất lớn. Phân loại theo nguồn gốc và phản ứng trùng hợp / trùng ngưng.", ["Trùng hợp: PE, PVC, PS, Cao su Buna", "Trùng ngưng: Nilon-6,6, Tơ lapsan"], ["Hệ số trùng hợp n: M_polime = n × M_mắt xích"], ["Tơ visco và tơ axetat là tơ bán tổng hợp (nhân tạo)."], "Tơ tằm, tơ nilon-6,6, tơ visco: chất nào là tơ bán tổng hợp?", "Tơ visco.", ["ETHANOL", "CARBON"]),
    (13, 4, "Bài 13: Vật liệu Polymer: Chất dẻo, Tơ, Cao su & Keo dán", "Chất dẻo (PE, PVC, Plexiglas PMMA). Tơ nilon-6,6. Cao su lưu hóa tăng độ đàn hồi.", ["Thủy tinh hữu cơ Plexiglas: Poli(metyl metacrylat) PMMA", "Cao su lưu hóa có cầu nối đisunfua -S-S- tạo mạng 3D"], ["Tơ nilon kém bền trong môi trường kiềm và axit."], ["Cao su không thấm nước và khí."], "Tại sao không giặt quần áo may bằng tơ nilon trong nước kiềm nóng?", "Vì liên kết peptit -CO-NH- dễ bị thủy phân làm mủn vải.", ["TRIGLYCERIDE", "NaOH", "WATER"]),
    (14, 4, "Bài 14: Ôn tập chương 4", "Phân biệt trùng hợp và trùng ngưng, nhận diện monome và tính toán hệ số trùng hợp.", ["Bảng tổng kết các loại Polime quan trọng"], ["M_polime = n × M_monome"], ["Thành thạo bài toán điều chế cao su."], "Trùng hợp monome nào thu được nhựa Teflon chống dính?", "Tetrafloetilen (CF2=CF2).", ["ETHANOL", "CARBON"]),
    (15, 5, "Bài 15: Thế điện cực & Nguồn điện hóa học (Pin điện)", "Cặp oxi hóa - khử M^(n+)/M. Dãy thế điện cực chuẩn E°. Suất điện động E°_pin = E°_catot - E°_anot.", ["E°_pin = E°_dương (Catot) - E°_âm (Anot) > 0", "Quy tắc alpha (α): Oxh mạnh + Khử mạnh → Oxh yếu + Khử yếu"], ["Pin Galvani Zn - Cu: Zn | Zn²⁺ || Cu²⁺ | Cu  E°_pin = +1,10 V"], ["Kim loại có E° càng âm thì tính khử càng mạnh."], "Tính E°_pin của pin Zn - Cu biết E°(Zn2+/Zn) = -0,76V và E°(Cu2+/Cu) = +0,34V?", "E°_pin = 0,34 - (-0,76) = +1,10 V.", ["Zn", "CuSO4", "Fe", "Cu"]),
    (16, 5, "Bài 16: Điện phân (Electrolysis)", "Quá trình oxi hóa - khử xảy ra trên điện cực dưới tác dụng của dòng điện. Anot (+) xảy ra oxh; Catot (-) xảy ra khử.", ["Anot (+): Oxi hóa (Nhường e) | Catot (-): Khử (Nhận e)", "Định luật Faraday: m = (A × I × t) / (n × F)"], ["Điện phân dd CuSO₄: 2CuSO₄ + 2H₂O → 2Cu ↓ (Catot) + O₂ ↑ (Anot) + 2H₂SO₄", "Điện phân nóng chảy NaCl: 2NaCl → 2Na + Cl₂ ↑"], ["Ứng dụng mạ điện và luyện kim."], "Trong điện phân dd CuSO4, ở cực âm (Catot) xảy ra quá trình gì?", "Quá trình khử ion Cu²⁺ thành kim loại Cu (Cu²⁺ + 2e → Cu).", ["CuSO4", "NaCl", "WATER", "SODIUM"]),
    (17, 5, "Bài 17: Ôn tập chương 5", "Hệ thống hóa pin điện hóa, thứ tự điện phân các ion và bài toán Faraday.", ["Thứ tự Catot (-): Ag⁺ > Fe³⁺ > Cu²⁺ > H⁺ > Fe²⁺ > Zn²⁺ > H₂O", "Thứ tự Anot (+): S²⁻ > I⁻ > Br⁻ > Cl⁻ > H₂O"], ["m = (AIt) / (nF)"], ["Thành thạo bài toán điện phân hỗn hợp muối."], "Điện phân dd chứa AgNO3 và Cu(NO3)2, kim loại nào kết tủa đầu tiên ở Catot?", "Bạc (Ag) vì ion Ag+ có tính oxi hóa mạnh hơn Cu2+.", ["AgNO3", "CuSO4", "NaCl", "WATER"]),
    (18, 6, "Bài 18: Cấu tạo & Liên kết trong Tinh thể kim loại", "Mạng lập phương tâm khối (BCC), lập phương tâm diện (FCC) và lục giác chặt khít (HCP).", ["BCC: Li, Na, K, Ba, Cr, Fe_α (68%)", "FCC: Cu, Ag, Au, Al, Fe_γ (74%)", "HCP: Be, Mg, Zn (74%)"], ["Liên kết kim loại do cation kim loại hút khí electron tự do."], ["Mạng tinh thể quyết định khối lượng riêng và độ cứng."], "Kim loại kiềm (Li, Na, K) có kiểu mạng tinh thể nào?", "Mạng lập phương tâm khối (BCC).", ["SODIUM", "POTASSIUM", "Fe", "Cu", "Al"]),
    (19, 6, "Bài 19: Tính chất vật lí & Tính chất hóa học của kim loại", "Tính chất chung (Dẻo, Dẫn điện, Dẫn nhiệt, Ánh kim) do electron tự do. Tính chất hóa học: tính khử (M → M^(n+) + ne).", ["Tính khử: Tác dụng phi kim, axit, nước và dung dịch muối"], ["M nhường e trở thành ion dương Mⁿ⁺"], ["Dẻo nhất là Au; dẫn điện tốt nhất là Ag; nóng chảy cao nhất là Vonfram (3422°C)."], "Nguyên nhân tạo nên tính chất vật lí chung của kim loại?", "Do các electron tự do di chuyển hỗn loạn trong mạng tinh thể.", ["Cu", "Fe", "Al", "Zn"]),
